CREATE TABLE agent_activity (id INTEGER PRIMARY KEY AUTOINCREMENT, agent_slug TEXT NOT NULL, action TEXT NOT NULL, target_kind TEXT, target_id TEXT, summary TEXT, meta TEXT, ts TEXT NOT NULL DEFAULT (datetime('now')));

CREATE TABLE notes (
  id            TEXT PRIMARY KEY,        -- "folder/stem"
  folder        TEXT NOT NULL,
  filename      TEXT NOT NULL,
  title         TEXT NOT NULL DEFAULT '',
  date          TEXT DEFAULT '',
  type          TEXT DEFAULT '',
  tags          TEXT DEFAULT '[]',        -- JSON array
  status        TEXT DEFAULT '',
  tasks         TEXT DEFAULT '[]',        -- JSON array
  body          TEXT DEFAULT '',
  meta          TEXT DEFAULT '{}',        -- JSON blob (full frontmatter)
  content_hash  TEXT DEFAULT '',
  updated_at    TEXT DEFAULT (datetime('now')),
  dirty         INTEGER DEFAULT 0
, ref_code TEXT DEFAULT NULL, body_html TEXT DEFAULT NULL, canvas TEXT DEFAULT NULL, canvas_preview TEXT DEFAULT NULL, author TEXT DEFAULT NULL);

CREATE TABLE task_stamps (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  task_id    TEXT NOT NULL,
  kind       TEXT NOT NULL CHECK (kind IN ('release', 'merge')),
  pr_url     TEXT,
  head_sha   TEXT,
  stamped_by TEXT NOT NULL,
  stamped_at TEXT DEFAULT (datetime('now'))
);

CREATE TABLE tasks (
  id          TEXT PRIMARY KEY,
  note_id     TEXT NOT NULL,
  parent_id   TEXT DEFAULT '',
  text        TEXT NOT NULL,
  description TEXT DEFAULT '',
  done        INTEGER DEFAULT 0,
  due_date    TEXT DEFAULT '',
  position    INTEGER DEFAULT 0,
  created_at  TEXT DEFAULT (datetime('now')),
  updated_at  TEXT DEFAULT (datetime('now')), assignee TEXT, dispatch_status TEXT, dispatch_run_id TEXT, dispatch_started_at TEXT, dispatch_completed_at TEXT, dispatch_blocker TEXT, last_pm_review TEXT, dispatch_owner TEXT, dispatch_result_ref TEXT, dispatch_pr_url TEXT, origin TEXT NOT NULL DEFAULT 'unknown',
  FOREIGN KEY (note_id) REFERENCES notes(id) ON DELETE CASCADE
);

CREATE INDEX idx_agent_activity_agent ON agent_activity(agent_slug, ts DESC);

CREATE INDEX idx_agent_activity_ts ON agent_activity(ts DESC);

CREATE INDEX idx_notes_author ON notes(author);

CREATE INDEX idx_notes_client ON notes(json_extract(meta, '$.client'));

CREATE INDEX idx_notes_date   ON notes(date);

CREATE INDEX idx_notes_folder ON notes(folder);

CREATE UNIQUE INDEX idx_notes_ref_code ON notes(ref_code);

CREATE INDEX idx_notes_status ON notes(status);

CREATE INDEX idx_task_stamps_task ON task_stamps(task_id, kind);

