CREATE TRIGGER tasks_origin_immutable BEFORE UPDATE OF origin ON tasks
WHEN NEW.origin <> OLD.origin
BEGIN SELECT RAISE(ABORT, 'task origin is immutable'); END;

CREATE TRIGGER tasks_queue_guard_ins BEFORE INSERT ON tasks
WHEN lower(trim(NEW.dispatch_status)) = 'queued'
  AND NEW.origin NOT IN ('jeremie', 'system', 'client')
  AND NOT EXISTS (SELECT 1 FROM task_stamps s WHERE s.task_id = NEW.id AND s.kind = 'release')
BEGIN SELECT RAISE(ABORT, 'tainted task needs a human stamp'); END;

CREATE TRIGGER tasks_queue_guard_upd BEFORE UPDATE OF dispatch_status ON tasks
WHEN lower(trim(NEW.dispatch_status)) = 'queued' AND lower(trim(COALESCE(OLD.dispatch_status, ''))) <> 'queued'
  AND NEW.origin NOT IN ('jeremie', 'system', 'client')
  AND NOT EXISTS (SELECT 1 FROM task_stamps s WHERE s.task_id = NEW.id AND s.kind = 'release')
BEGIN SELECT RAISE(ABORT, 'tainted task needs a human stamp'); END;
